#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    // No arguments besides program name
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    // Only x provided, no coefficients
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }
    // Maximum supported arguments: program name + x + up to 12 coefficients (total 14)
    if (argc > 14) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Parse x (the evaluation point)
    char *endptr;
    long long x = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (x < -10 || x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    int coeff_count = argc - 2; // number of coefficients supplied
    long long coeffs[13]; // enough for the maximum allowed
    for (int i = 0; i < coeff_count; ++i) {
        char *e;
        long long c = strtoll(argv[2 + i], &e, 10);
        if (e == argv[2 + i] || *e != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        if (c < -1000 || c > 1000) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        coeffs[i] = c;
    }

    // Horner's method evaluation
    long long result = 0;
    for (int i = 0; i < coeff_count; ++i) {
        result = result * x + coeffs[i];
    }
    printf("%lld\n", result);
    return 0;
}
